actions.script:
import org.moqui.entity.EntityList
import org.moqui.entity.EntityValue

// Initialize output parameters
validationResults = []
totalCount = 0
failedCount = 0

// Query FiscalTaxDocuments within the date range
def findBuilder = ec.entity.find("mchile.dte.FiscalTaxDocument")
    .condition("date", ">=", fromDate)
    .condition("date", "<=", thruDate)
    .condition("statusId", "Ftd-Issued")
    .orderBy("date")

// Add optional document type filter
if (fiscalTaxDocumentTypeEnumId) {
    findBuilder.condition("fiscalTaxDocumentTypeEnumId", fiscalTaxDocumentTypeEnumId)
}

def fiscalTaxDocuments = findBuilder.list()
totalCount = fiscalTaxDocuments.size()

ec.logger.info("Starting batch DTE validation for ${totalCount} documents from ${fromDate} to ${thruDate}")

// Process each FiscalTaxDocument
for (EntityValue ftd : fiscalTaxDocuments) {
    String fiscalTaxDocumentId = ftd.fiscalTaxDocumentId

    try {
        // Call validate#DteFromOrder service
        Map validateResult = ec.service.sync()
            .name("mchile.sii.dte.DteValidationServices.validate#DteFromOrder")
            .parameter("fiscalTaxDocumentId", fiscalTaxDocumentId)
            .call()

        // Check if validation passed
        Boolean validationPassed = validateResult.validationPassed

        if (!validationPassed) {
            failedCount++

            // Add to failed results
            validationResults.add([
                fiscalTaxDocumentId: fiscalTaxDocumentId,
                fiscalTaxDocumentNumber: ftd.fiscalTaxDocumentNumber,
                date: ftd.date,
                validationPassed: validationPassed,
                discrepancies: validateResult.discrepancies ?: [],
                generationError: validateResult.generationError,
                clonedOrderId: validateResult.clonedOrderId
            ])

            ec.logger.warn("Validation failed for FiscalTaxDocument ${fiscalTaxDocumentId} (Folio: ${ftd.fiscalTaxDocumentNumber})")
        } else {
            ec.logger.info("Validation passed for FiscalTaxDocument ${fiscalTaxDocumentId} (Folio: ${ftd.fiscalTaxDocumentNumber})")
        }

    } catch (Exception e) {
        failedCount++

        // Add exception as a failed result
        validationResults.add([
            fiscalTaxDocumentId: fiscalTaxDocumentId,
            fiscalTaxDocumentNumber: ftd.fiscalTaxDocumentNumber,
            date: ftd.date,
            validationPassed: false,
            discrepancies: [],
            generationError: "Exception during validation: ${e.message}",
            clonedOrderId: null
        ])

        ec.logger.error("Exception validating FiscalTaxDocument ${fiscalTaxDocumentId}: ${e.message}", e)
    }
}

ec.logger.info("Batch DTE validation complete: ${totalCount} total, ${failedCount} failed, ${totalCount - failedCount} passed")
